"use client";

import {
  useCallback,
  useEffect,
  useId,
  useImperativeHandle,
  useLayoutEffect,
  useRef,
  useState,
  type KeyboardEvent,
  type Ref,
} from "react";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import {
  Command,
  CommandEmpty,
  CommandInput,
  CommandList,
} from "@/components/ui/command";
import type {
  EntityLike,
  EntityPickerHandle,
  EntityPickerProps,
  KindMeta,
  MultiPickerProps,
  PickerMode,
  SinglePickerProps,
} from "./types";
import { defaultMatch } from "./lib/default-match";
import { formatCount, resolveLabels } from "./lib/labels";
import {
  multiSelectionEqual,
  singleSelectionEqual,
} from "./lib/selection-equality";
import { useItemsById } from "./hooks/use-items-by-id";
import { useOpenState } from "./hooks/use-open-state";
import { useDirection } from "./hooks/use-direction";
import { TriggerButton } from "./parts/trigger-button";
import { ResultRow } from "./parts/result-row";
import { DefaultEmptyState } from "./parts/default-empty-state";
import { ErrorRow, LoadingRow } from "./parts/status-rows";

function EntityPickerImpl<T extends EntityLike>(props: EntityPickerProps<T>) {
  const {
    items,
    match,
    placeholder,
    query: controlledQuery,
    onQueryChange,
    filterItems = true,
    loading = false,
    error,
    onRetry,
    renderLoading,
    renderError,
    hasMore,
    onLoadMore,
    loadingMore = false,
    labels: labelsProp,
    locale,
    dir: dirProp,
    open: controlledOpen,
    onOpenChange,
    kinds,
    showKindBadges: showKindBadgesProp,
    renderItem,
    renderTrigger,
    renderEmpty,
    disabled = false,
    triggerLabel,
    id,
    className,
    ref,
  } = props;

  const mode: PickerMode = props.mode === "multi" ? "multi" : "single";
  const value = props.value as T | T[] | null;

  const reactId = useId();
  const listboxId = `${reactId}-listbox`;

  const { open, setOpen: rawSetOpen } = useOpenState({
    controlled: controlledOpen,
    onOpenChange,
  });

  const labels = resolveLabels(labelsProp);
  // Deprecated aliases win over their label keys. `triggerLabel` has always named
  // the trigger text, the trigger button and the search input.
  const searchPlaceholder = placeholder ?? labels.searchPlaceholder;
  const triggerPlaceholder = triggerLabel ?? labels.triggerPlaceholder;
  const searchLabel = triggerLabel ?? labels.searchLabel;

  const queryControlled = controlledQuery !== undefined;
  const [internalQuery, setInternalQuery] = useState("");
  const query = queryControlled ? controlledQuery : internalQuery;

  const onQueryChangeRef = useRef(onQueryChange);
  useLayoutEffect(() => {
    onQueryChangeRef.current = onQueryChange;
  });

  const handleQueryInput = useCallback((next: string) => {
    setInternalQuery(next);
    onQueryChangeRef.current?.(next, "input");
  }, []);

  const itemsById = useItemsById(items);

  // The one predicate behind the list: cmdk's `filter` and the announced count.
  const matchItem = useCallback(
    (item: T, search: string): boolean => {
      try {
        return match ? match(item, search) : defaultMatch(item, search, locale);
      } catch (err) {
        if (process.env.NODE_ENV !== "production") {
          console.error(
            `[entity-picker] match threw for item "${item.id}":`,
            err,
          );
        }
        return false;
      }
    },
    [match, locale],
  );

  const filterFn = useCallback(
    (entityId: string, search: string): number => {
      const item = itemsById.get(entityId);
      return item && matchItem(item, search) ? 1 : 0;
    },
    [itemsById, matchItem],
  );

  // Server mode: cmdk keeps its highlight on the row it was on when the list is
  // swapped, so the highlight is controlled there and returns to the first row
  // whenever the rows change (and when the popover closes).
  const [highlight, setHighlight] = useState<string>(items[0]?.id ?? "");
  const [prevItems, setPrevItems] = useState(items);
  if (prevItems !== items) {
    setPrevItems(items);
    const same =
      prevItems.length === items.length &&
      prevItems.every((it, i) => it.id === items[i].id);
    if (!same) setHighlight(items[0]?.id ?? "");
  }

  const [announcement, setAnnouncement] = useState("");
  const [prevOpen, setPrevOpen] = useState(open);
  const [prevLoading, setPrevLoading] = useState(loading);
  // Derived-state transitions (set during render, never in an effect): the
  // uncontrolled query clears when the popover closes, however it closes; the
  // results announcement is armed when loading settles while open, once.
  if (prevOpen !== open) {
    setPrevOpen(open);
    if (!open) {
      setInternalQuery("");
      setAnnouncement("");
      setHighlight(items[0]?.id ?? "");
    }
  }
  if (prevLoading !== loading) {
    setPrevLoading(loading);
    if (loading) {
      setAnnouncement("");
    } else if (open && !error) {
      // Count what the list shows: all rows in server mode, the matching rows
      // in client mode. An errored settle announces nothing (the alert speaks).
      const shown =
        filterItems && query !== ""
          ? items.filter((it) => matchItem(it, query)).length
          : items.length;
      setAnnouncement(labels.resultsCount(shown, formatCount(shown, locale)));
    }
  }

  // The host hears the reset after commit, for every way the popover can close
  // (selection, Esc, outside press, handle, a controlled `open` going false).
  const wasOpenRef = useRef(open);
  useEffect(() => {
    if (wasOpenRef.current && !open) onQueryChangeRef.current?.("", "reset");
    wasOpenRef.current = open;
  }, [open]);

  const setOpen = rawSetOpen;

  // Kind badges come from the rows AND the selection: chips must keep their
  // badge while `items` is empty (loading, server returned nothing).
  const selectedHasKind = Array.isArray(props.value)
    ? props.value.some((v) => !!v.kind)
    : !!props.value?.kind;
  const showKindBadges =
    showKindBadgesProp !== undefined
      ? showKindBadgesProp
      : items.some((i) => !!i.kind) || selectedHasKind;

  // Track the trigger element via state (not a ref) so the setter is React's
  // own setState — passes the React Compiler-aware lint rule that flags
  // ref-accessor functions passed to user-rendered functions during render.
  // The ref-fn is stable across renders (React guarantees setState identity).
  const [triggerNode, setTriggerNode] = useState<HTMLElement | null>(null);

  // The popover is portalled out of the host's layout, so it cannot inherit `dir`: resolve
  // it from the trigger (canonical useDirection snippet) and set it on the content.
  const popoverDir = useDirection(triggerNode, dirProp);

  // F-cross-13 consumer-trigger path: when a press lands while the popover is
  // open, Radix/Base UI's outside-press dismiss closes it BEFORE the click
  // event — the wrapper's click handler must not immediately re-open. The
  // capture-phase pointerdown snapshots the pre-dismiss open state.
  const openRef = useRef(open);
  // Layout effect: the capture-phase pointerdown guard reads this ref, and a
  // press can land between commit and a passive effect's flush.
  useLayoutEffect(() => {
    openRef.current = open;
  });
  const pointerDownWhileOpenRef = useRef(false);

  const handleSelect = useCallback(
    (item: T) => {
      if (mode === "multi") {
        const multiProps = props as MultiPickerProps<T>;
        const current = multiProps.value;
        const isSelected = current.some((v) => v.id === item.id);
        const next = isSelected
          ? current.filter((v) => v.id !== item.id)
          : [...current, item];
        if (!multiSelectionEqual(current, next)) {
          multiProps.onChange(next);
        }
      } else {
        const singleProps = props as SinglePickerProps<T>;
        const current = singleProps.value;
        const next = item;
        if (!singleSelectionEqual(current, next)) {
          singleProps.onChange(next);
        }
        setOpen(false);
      }
    },
    [mode, props, setOpen],
  );

  const handleRemoveChip = useCallback(
    (idToRemove: string) => {
      if (mode !== "multi") return;
      const multiProps = props as MultiPickerProps<T>;
      const next = multiProps.value.filter((v) => v.id !== idToRemove);
      if (!multiSelectionEqual(multiProps.value, next)) {
        multiProps.onChange(next);
      }
    },
    [mode, props],
  );

  const handleClear = useCallback(() => {
    if (mode === "multi") {
      const multiProps = props as MultiPickerProps<T>;
      if (multiProps.value.length > 0) multiProps.onChange([]);
    } else {
      const singleProps = props as SinglePickerProps<T>;
      if (singleProps.value !== null) singleProps.onChange(null);
    }
  }, [mode, props]);

  const focusTrigger = useCallback(() => {
    if (!triggerNode) return;
    triggerNode.focus();
  }, [triggerNode]);

  useImperativeHandle(
    ref as Ref<EntityPickerHandle>,
    (): EntityPickerHandle => ({
      focus: focusTrigger,
      open: () => setOpen(true),
      close: () => setOpen(false),
      clear: handleClear,
    }),
    [focusTrigger, setOpen, handleClear],
  );

  const handleTriggerKeyDown = useCallback(
    (e: KeyboardEvent<HTMLButtonElement>) => {
      if (disabled) return;
      if (e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        setOpen(true);
        return;
      }
      if (e.key === "ArrowDown") {
        e.preventDefault();
        setOpen(true);
      }
    },
    [disabled, setOpen],
  );

  const handleSearchKeyDown = useCallback(
    (e: KeyboardEvent<HTMLInputElement>) => {
      if (
        e.key === "Backspace" &&
        query.length === 0 &&
        mode === "multi"
      ) {
        const multiProps = props as MultiPickerProps<T>;
        if (multiProps.value.length > 0) {
          e.preventDefault();
          const last = multiProps.value[multiProps.value.length - 1];
          handleRemoveChip(last.id);
        }
      }
    },
    [query, mode, props, handleRemoveChip],
  );

  // F-cross-13: no `asChild` on either path. Default path — TriggerButton
  // renders the PopoverTrigger <button> internally. Consumer path — the node
  // can no longer BE the trigger (Slot semantics need asChild), so a hidden
  // full-size PopoverTrigger anchors the popover to the node's box while the
  // wrapper span owns open-on-click; the consumer node keeps its own
  // interactivity, hover styles, and the documented `triggerRef` contract.
  const renderTriggerNode = renderTrigger ? (
    <span
      className="relative inline-flex max-w-full"
      onPointerDownCapture={() => {
        pointerDownWhileOpenRef.current = openRef.current;
      }}
      onClick={(e) => {
        const wasOpen = pointerDownWhileOpenRef.current;
        pointerDownWhileOpenRef.current = false;
        if (disabled) return;
        // Keyboard "clicks" (detail 0) have no preceding pointerdown, so no
        // outside-press dismiss ran — toggle both ways here (Enter closes).
        if (e.detail === 0) {
          setOpen(!openRef.current);
          return;
        }
        if (wasOpen) return;
        setOpen(true);
      }}
    >
      <PopoverTrigger
        aria-hidden="true"
        tabIndex={-1}
        // Close-autofocus lands here (it's the backend's registered trigger);
        // bounce it to the consumer's real trigger element.
        onFocus={() => triggerNode?.focus()}
        className="pointer-events-none absolute inset-0"
      />
      {renderTrigger({
        value,
        open,
        triggerRef: setTriggerNode,
      })}
    </span>
  ) : (
    <TriggerButton<T>
      ref={setTriggerNode}
      id={id}
      mode={mode}
      value={value}
      open={open}
      disabled={disabled}
      triggerLabel={triggerLabel}
      placeholderText={triggerPlaceholder}
      removeChipLabel={labels.removeChip}
      kinds={kinds}
      showKindBadges={showKindBadges}
      listboxId={listboxId}
      className={className}
      onKeyDown={handleTriggerKeyDown}
      onRemoveChip={handleRemoveChip}
    />
  );

  const valueMap = (() => {
    const out = new Set<string>();
    if (mode === "multi") {
      const m = props as MultiPickerProps<T>;
      for (const v of m.value) out.add(v.id);
    } else {
      const s = props as SinglePickerProps<T>;
      if (s.value) out.add(s.value.id);
    }
    return out;
  })();

  const errorActive = !loading && !!error;
  const errorMessage = typeof error === "string" ? error : labels.error;
  const emptyNode = renderEmpty ? (
    renderEmpty({ query, itemCount: items.length })
  ) : (
    <DefaultEmptyState
      query={query}
      itemCount={items.length}
      nothingToPick={labels.nothingToPick}
      noResults={labels.noResults}
      serverFiltered={!filterItems}
    />
  );

  return (
    <Popover open={open} onOpenChange={setOpen}>
      {renderTriggerNode}
      <PopoverContent
        id={listboxId}
        dir={popoverDir}
        align="start"
        sideOffset={4}
        aria-label={searchLabel}
        // Radix exposes --radix-popover-trigger-width, Base UI --anchor-width
        // (F-cross-13) — cover both; min-w-60 is the last-resort floor.
        className="w-(--radix-popover-trigger-width,var(--anchor-width)) min-w-60 p-0"
      >
        {/* cmdk names the input through its own `label` (aria-labelledby wins
            over aria-label), so the search name must be passed here too. */}
        <Command
          label={searchLabel}
          filter={filterFn}
          shouldFilter={filterItems}
          value={filterItems ? undefined : highlight}
          onValueChange={setHighlight}
          loop
        >
          <CommandInput
            placeholder={searchPlaceholder}
            value={query}
            onValueChange={handleQueryInput}
            onKeyDown={handleSearchKeyDown}
            aria-label={searchLabel}
          />
          <CommandList
            label={labels.listLabel}
            aria-multiselectable={mode === "multi"}
            aria-busy={loading || undefined}
          >
            {filterItems && !loading && !errorActive ? (
              <CommandEmpty>{emptyNode}</CommandEmpty>
            ) : null}
            {items.map((item) => {
              const selected = valueMap.has(item.id);
              const kindMeta: KindMeta | undefined =
                item.kind && kinds ? kinds[item.kind] : undefined;
              const customNode = renderItem
                ? renderItem(item, { selected, query })
                : undefined;
              return (
                <ResultRow<T>
                  key={item.id}
                  item={item}
                  selected={selected}
                  kindMeta={kindMeta}
                  showKindBadges={showKindBadges}
                  selectedText={labels.selectedState}
                  onSelect={() => handleSelect(item)}
                  customRender={customNode}
                />
              );
            })}
          </CommandList>
          {/* Status rows and Load more sit beside the listbox, not inside it: a
              listbox may only own options, and status/alert children fail axe.
              cmdk's root swallows Enter (preventDefault + selects the
              highlighted row), so Enter/Space on these controls must not
              bubble to it or the button never clicks. */}
          <div
            data-slot="entity-picker-footer"
            onKeyDown={(e) => {
              if (e.key === "Enter" || e.key === " ") e.stopPropagation();
            }}
          >
          {loading
            ? renderLoading
              ? renderLoading({ query, itemCount: items.length })
              : <LoadingRow text={labels.loading} />
            : null}
          {errorActive
            ? renderError
              ? renderError({ message: errorMessage, query, onRetry })
              : (
                  <ErrorRow
                    message={errorMessage}
                    retryText={labels.retry}
                    onRetry={onRetry}
                  />
                )
            : null}
          {!filterItems && !loading && !errorActive && items.length === 0
            ? emptyNode
            : null}
          {hasMore && onLoadMore ? (
            <button
              type="button"
              data-slot="entity-picker-load-more"
              // aria-disabled, not disabled: a disabled button drops keyboard focus to <body>
              // the moment the host sets loadingMore, stranding the user outside the popover.
              aria-disabled={loadingMore || undefined}
              onClick={() => {
                if (!loadingMore) onLoadMore();
              }}
              className="flex w-full items-center justify-center rounded-sm px-2 py-1.5 text-xs text-muted-foreground outline-none transition-colors hover:bg-muted hover:text-foreground focus-visible:ring-3 focus-visible:ring-ring/50 aria-disabled:cursor-default aria-disabled:opacity-50 aria-disabled:hover:bg-transparent aria-disabled:hover:text-muted-foreground"
            >
              {loadingMore ? labels.loading : labels.loadMore}
            </button>
          ) : null}
          </div>
          <div
            aria-live="polite"
            aria-atomic="true"
            data-slot="entity-picker-announcer"
            className="sr-only"
          >
            {open ? announcement : ""}
          </div>
        </Command>
      </PopoverContent>
    </Popover>
  );
}

export function EntityPicker<T extends EntityLike>(
  props: SinglePickerProps<T>,
): React.JSX.Element;
export function EntityPicker<T extends EntityLike>(
  props: MultiPickerProps<T>,
): React.JSX.Element;
export function EntityPicker<T extends EntityLike>(
  props: EntityPickerProps<T>,
): React.JSX.Element {
  return EntityPickerImpl(props);
}

export { EntityPicker } from "./entity-picker";
export { defaultEntityPickerLabels } from "./types";
export type {
  CommonPickerProps,
  EntityLike,
  EntityPickerHandle,
  EntityPickerLabels,
  EntityPickerProps,
  KindMeta,
  MultiPickerProps,
  PickerMode,
  RenderEmptyContext,
  RenderErrorContext,
  RenderItemContext,
  RenderLoadingContext,
  RenderTriggerContext,
  SinglePickerProps,
} from "./types";

// @ilinxa/entity-picker 0.2.0

import type { ReactNode, Ref } from "react";

export interface EntityLike {
  id: string;
  label: string;
  kind?: string;
}

export interface KindMeta {
  label: string;
  color?: string;
}

export type PickerMode = "single" | "multi";

export interface RenderItemContext {
  selected: boolean;
  query: string;
}

export interface RenderTriggerContext<T extends EntityLike> {
  value: T | T[] | null;
  open: boolean;
  triggerRef: (node: HTMLElement | null) => void;
}

export interface RenderEmptyContext {
  query: string;
  itemCount: number;
}

export interface RenderLoadingContext {
  query: string;
  /** Rows currently shown (loading can overlay existing rows). */
  itemCount: number;
}

export interface RenderErrorContext {
  /** The `error` string, or `labels.error` when `error` is `true`. */
  message: string;
  query: string;
  /** Present only when the host passed `onRetry`. */
  onRetry?: () => void;
}

/** User-facing strings. Every key is optional on the prop; an `undefined` key keeps the default. */
export interface EntityPickerLabels {
  /** Search input placeholder. Default: "Search…". */
  searchPlaceholder: string;
  /** Accessible name of the search input. Default: "Search entities". */
  searchLabel: string;
  /** Text shown in the trigger while nothing is selected. Default: "Select…". */
  triggerPlaceholder: string;
  /** Accessible name of a chip's remove button. Default: `Remove ${label}`. */
  removeChip: (label: string) => string;
  /** Empty state when there are no items at all. Default: "Nothing to pick from". */
  nothingToPick: string;
  /** Empty state when a search matches nothing. Default: "No results". */
  noResults: string;
  /** Loading row text. Default: "Loading…". */
  loading: string;
  /** Error row text when `error` is `true`. Default: "Something went wrong". */
  error: string;
  /** Retry button text (rendered only with `onRetry`). Default: "Retry". */
  retry: string;
  /** "Load more" row text. Default: "Load more". */
  loadMore: string;
  /**
   * Polite announcement once loading settles while open. Receives the raw count and the
   * `locale`-formatted one. Default: "3 results".
   */
  resultsCount: (count: number, formatted: string) => string;
  /** Accessible name of the results listbox. Default: "Suggestions". */
  listLabel: string;
  /**
   * Visually hidden text appended to a chosen row so screen readers can tell chosen rows from
   * the highlighted one. Default: "selected".
   */
  selectedState: string;
}

/** Default English labels, exported for consumer composition. */
export const defaultEntityPickerLabels: EntityPickerLabels = {
  searchPlaceholder: "Search…",
  searchLabel: "Search entities",
  triggerPlaceholder: "Select…",
  removeChip: (label) => `Remove ${label}`,
  nothingToPick: "Nothing to pick from",
  noResults: "No results",
  loading: "Loading…",
  error: "Something went wrong",
  retry: "Retry",
  loadMore: "Load more",
  resultsCount: (count, formatted) => `${formatted} ${count === 1 ? "result" : "results"}`,
  listLabel: "Suggestions",
  selectedState: "selected",
};

export interface CommonPickerProps<T extends EntityLike> {
  items: ReadonlyArray<T>;

  match?: (item: T, query: string) => boolean;
  /** @deprecated Use `labels.searchPlaceholder`. When set it wins over the label. */
  placeholder?: string;

  /** Controlled search text; wins on every render. Omit for the uncontrolled input (resets on close). */
  query?: string;
  /**
   * Called when the search text changes (`"input"`) and when the picker closes and clears it
   * (`"reset"`, always with `""`).
   */
  onQueryChange?: (query: string, reason: "input" | "reset") => void;
  /**
   * `false` turns the built-in filtering off: `items` render as given (server-side search) and
   * `match` is ignored. Default `true`.
   */
  filterItems?: boolean;

  /** Show the loading row (and `aria-busy` on the list). Wins over `error` and the empty state. */
  loading?: boolean;
  /** `true` shows `labels.error`; a string shows that text. Ignored while `loading`. */
  error?: boolean | string;
  /** Retry handler. The Retry button renders only when this is given. */
  onRetry?: () => void;
  renderLoading?: (ctx: RenderLoadingContext) => ReactNode;
  renderError?: (ctx: RenderErrorContext) => ReactNode;

  /** More pages exist. The "Load more" row renders only with both `hasMore` and `onLoadMore`. */
  hasMore?: boolean;
  onLoadMore?: () => void;
  /** A page is being fetched: the "Load more" row shows the loading text and is disabled. */
  loadingMore?: boolean;

  labels?: Partial<EntityPickerLabels>;
  /** BCP 47 tag for the default match's case folding and the results count format. */
  locale?: string;
  /**
   * Direction of the popover. It renders in a portal, outside your layout, so it cannot
   * inherit `dir`. Default: the trigger's direction, read after the trigger mounts. Pass it if the
   * app switches direction at runtime without remounting.
   */
  dir?: "ltr" | "rtl";

  open?: boolean;
  onOpenChange?: (open: boolean) => void;

  kinds?: Record<string, KindMeta>;
  showKindBadges?: boolean;

  renderItem?: (item: T, ctx: RenderItemContext) => ReactNode;
  renderTrigger?: (ctx: RenderTriggerContext<T>) => ReactNode;
  renderEmpty?: (ctx: RenderEmptyContext) => ReactNode;

  disabled?: boolean;
  /**
   * @deprecated Use `labels.triggerPlaceholder` / `labels.searchLabel`. When set it wins over
   * both and also names the trigger button.
   */
  triggerLabel?: string;
  id?: string;
  className?: string;

  ref?: Ref<EntityPickerHandle>;
}

export interface SinglePickerProps<T extends EntityLike>
  extends CommonPickerProps<T> {
  mode?: "single";
  value: T | null;
  onChange: (value: T | null) => void;
}

export interface MultiPickerProps<T extends EntityLike>
  extends CommonPickerProps<T> {
  mode: "multi";
  value: T[];
  onChange: (value: T[]) => void;
}

export type EntityPickerProps<T extends EntityLike> =
  | SinglePickerProps<T>
  | MultiPickerProps<T>;

export interface EntityPickerHandle {
  focus(): void;
  open(): void;
  close(): void;
  clear(): void;
}

"use client";

import { useEffect, useMemo, useRef } from "react";
import type { EntityLike } from "../types";

export function useItemsById<T extends EntityLike>(
  items: ReadonlyArray<T>,
): Map<string, T> {
  const map = useMemo(() => {
    const out = new Map<string, T>();
    for (const item of items) {
      if (out.has(item.id)) {
        if (process.env.NODE_ENV !== "production") {
          console.error(
            `[entity-picker] duplicate id "${item.id}" in items; later occurrences are ignored.`,
          );
        }
        continue;
      }
      out.set(item.id, item);
    }
    return out;
  }, [items]);

  // Runs after EVERY render (no deps): a render with the same `items` resets the count, so
  // only an array that changes on consecutive renders warns — not a host that swaps `items`
  // when a server search returns (renders in between keep the same array).
  const stabilityRef = useRef({ last: items, count: 0, warned: false });
  useEffect(() => {
    const tracker = stabilityRef.current;
    if (tracker.last === items) {
      tracker.count = 0;
      return;
    }
    tracker.last = items;
    tracker.count++;
    if (
      tracker.count > 5 &&
      !tracker.warned &&
      process.env.NODE_ENV !== "production"
    ) {
      tracker.warned = true;
      console.warn(
        "[entity-picker] `items` prop is changing every render. " +
          "Wrap with `useMemo` or hoist to module scope to avoid re-derivation.",
      );
    }
  });

  return map;
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";

interface UseOpenStateArgs {
  controlled: boolean | undefined;
  onOpenChange: ((open: boolean) => void) | undefined;
}

interface UseOpenStateResult {
  open: boolean;
  setOpen: (next: boolean) => void;
}

export function useOpenState({
  controlled,
  onOpenChange,
}: UseOpenStateArgs): UseOpenStateResult {
  const isControlled = controlled !== undefined;
  const [internalOpen, setInternalOpen] = useState(false);

  const onOpenChangeRef = useRef(onOpenChange);
  useEffect(() => {
    onOpenChangeRef.current = onOpenChange;
  });

  const setOpen = useCallback(
    (next: boolean) => {
      if (!isControlled) setInternalOpen(next);
      onOpenChangeRef.current?.(next);
    },
    [isControlled],
  );

  const open = isControlled ? (controlled as boolean) : internalOpen;
  return { open, setOpen };
}

import type { EntityLike } from "../types";

function fold(text: string, locale: string | undefined): string {
  if (!locale) return text.toLowerCase();
  try {
    return text.toLocaleLowerCase(locale);
  } catch {
    // Invalid BCP 47 tag: fall back rather than hide every item.
    return text.toLowerCase();
  }
}

export function defaultMatch<T extends EntityLike>(
  item: T,
  query: string,
  locale?: string,
): boolean {
  if (query.length === 0) return true;
  return fold(item.label, locale).includes(fold(query, locale));
}

import type { EntityLike } from "../types";

export function valueToArray<T extends EntityLike>(
  value: T | T[] | null,
): T[] {
  if (value === null || value === undefined) return [];
  if (Array.isArray(value)) return value;
  return [value];
}

export function valueIds<T extends EntityLike>(
  value: T | T[] | null,
): Set<string> {
  const out = new Set<string>();
  for (const item of valueToArray(value)) out.add(item.id);
  return out;
}

export function hasId<T extends EntityLike>(
  value: T | T[] | null,
  id: string,
): boolean {
  if (value === null || value === undefined) return false;
  if (Array.isArray(value)) return value.some((v) => v.id === id);
  return value.id === id;
}

import type { EntityLike } from "../types";

export function singleSelectionEqual<T extends EntityLike>(
  a: T | null,
  b: T | null,
): boolean {
  if (a === null && b === null) return true;
  if (a === null || b === null) return false;
  return a.id === b.id;
}

export function multiSelectionEqual<T extends EntityLike>(
  a: ReadonlyArray<T>,
  b: ReadonlyArray<T>,
): boolean {
  if (a.length !== b.length) return false;
  if (a.length === 0) return true;
  const seen = new Set<string>();
  for (const item of a) seen.add(item.id);
  for (const item of b) {
    if (!seen.has(item.id)) return false;
  }
  return true;
}

